447	fn parse_inner<'a>(
448	    source: &'a [u8],
449	    tokens: &[XmlToken],
450	    meter: &mut Meter<'_>,
451	) -> Result<Document<'a>, ParseError> {
452	    let mut d = Document {
453	        source,
454	        tracks: Vec::new(),
455	        diagnostics: Vec::new(),
456	    };
457	    d.tracks
458	        .try_reserve_exact(MAX_TRACKS)
459	        .map_err(|_| ParseError::Allocation)?;
460	    d.diagnostics
461	        .try_reserve_exact(MAX_DIAGNOSTICS)
462	        .map_err(|_| ParseError::Allocation)?;
463	    let mut allocation_failed = false;
464	    for (i, t) in tokens.iter().enumerate() {
465	        if !meter.charge(WorkKind::TokenVisit, 1) {
466	            break;
467	        }
468	        if !meter.charge(
469	            WorkKind::SourceRead,
470	            t.name
471	                .length
472	                .saturating_add(t.local_name.length)
473	                .saturating_add(t.value.length),
474	        ) {
475	            break;
476	        }
477	        if !matches!(t.kind, TokenKind::StartElement | TokenKind::EmptyElement) {
478	            continue;
479	        }
480	        let name = span(source, t.local_name).unwrap_or_default();
481	        if t.prefix.length == 0 && name == b"style" {
482	            for x in tokens
483	                .iter()
484	                .skip(i + 1)
485	                .take_while(|x| !(x.kind == TokenKind::EndElement && x.depth == t.depth))
486	            {
487	                if !meter.charge(WorkKind::TokenVisit, 1) {
488	                    break;
489	                }
490	                if x.kind == TokenKind::Text {
491	                    if let Some(b) = span(source, x.value) {
492	                        if !meter.charge(WorkKind::SourceRead, b.len()) {
493	                            break;
494	                        }
495	                        if [b"@keyframes".as_slice(), b"animation:", b"transition:"]
496	                            .iter()
497	                            .any(|n| b.windows(n.len()).any(|w| w == *n))
498	                        {
499	                            diagnostic(&mut d, DiagnosticKind::CssAnimation, x.value.offset)
500	                        }
501	                    }
502	                }
503	            }
504	        }
505	        if t.prefix.length != 0
506	            || !matches!(
507	                name,
508	                b"animate" | b"animateTransform" | b"set" | b"animateMotion" | b"animateColor"
509	            )
510	        {
511	            continue;
512	        }
513	        if d.tracks.len() >= MAX_TRACKS {
514	            return Err(ParseError::TrackLimit {
515	                offset: t.name.offset,
516	            });
517	        }
518	        let mut parent = None;
519	        for j in (0..i).rev() {
520	            if !meter.charge(WorkKind::TokenVisit, 1) {
521	                break;
522	            }
523	            if matches!(
524	                tokens[j].kind,
525	                TokenKind::StartElement | TokenKind::EmptyElement
526	            ) && tokens[j].depth + 1 == t.depth
527	            {
528	                parent = Some(j);
529	                break;
530	            }
531	        }
532	        if meter.stop().is_some() {
533	            break;
534	        }
535	        let Some(parent) = parent else {
536	            diagnostic(&mut d, DiagnosticKind::InvalidTrack, t.name.offset);
537	            continue;
538	        };
539	        if let Some(track) = parse_track(
540	            source,
541	            tokens,
542	            i,
543	            parent,
544	            &mut d,
545	            &mut allocation_failed,
546	            meter,
547	        ) {
548	            d.tracks.push(track)
549	        }
550	        if allocation_failed {
551	            return Err(ParseError::Allocation);
552	        }
553	    }
554	    // Resolve syncbase identifiers only after every supported track has been collected.
555	    for i in 0..d.tracks.len() {
556	        if !meter.charge(WorkKind::AnimationTransform, 1) {
557	            break;
558	        }
559	        for begin in [true, false] {
560	            let id = if begin {
561	                d.tracks[i].begin_sync_id
562	            } else {
563	                d.tracks[i].end_sync_id
564	            };
565	            let Some(id) = id else { continue };
566	            let needle = span(source, id).unwrap_or_default();
567	            let mut found = None;
568	            let mut match_count = 0;
569	            for (j, track) in d.tracks.iter().enumerate() {
570	                if !meter.charge(WorkKind::ReferenceProbe, 1) {
571	                    break;
572	                }
573	                if track.id.length > 0 && span(source, track.id) == Some(needle) {
574	                    found = Some(j);
575	                    match_count += 1;
576	                }
577	            }
578	            if match_count != 1 {
579	                diagnostic(&mut d, DiagnosticKind::UnsupportedTiming, id.offset);
580	                d.tracks[i].supported = false
581	            } else if begin {
582	                d.tracks[i].begin_sync_track = found
583	            } else {
584	                d.tracks[i].end_sync_track = found
585	            }
586	        }
587	    }
588	    if meter.stop().is_some() {
589	        return Err(ParseError::Allocation);
590	    }
591	    // Cycles are retained as unsupported timing and resolved by evaluator to inactive tracks.
592	    Ok(d)
593	}
